import React, { Component} from 'react';
import {
  Box,
  Button,
  Heading,
  Grommet,
  FormField,
  Form,
  Text
} from 'grommet';
import { Home as HomeIcon, User, Lock, Add } from 'grommet-icons';

import './App.css';

const theme = {
  global: {
    colors: {
      brand: {
        dark: '#667eea',
        light: '#764ba2'
      },
      focus: '#4A90E2',
      text: {
        dark: '#2c3e50',
        light: '#7f8c8d'
      },
      background: {
        light: '#f8f9fa',
        dark: '#2c3e50'
      }
    },
    font: {
      family: '"Segoe UI", Tahoma, Geneva, Verdana, sans-serif',
      weight: 400
    }
  },
  button: {
    border: {
      radius: '8px'
    },
    primary: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white'
    }
  },
  formField: {
    border: {
      radius: '8px'
    }
  }
};

const AppBar = (props) => (
  <Box
    className="professional-header"
    pad='medium'
    elevation='medium'
    justify='between'
    direction='row'
    align='center'
    style={{ 
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      boxShadow: '0 2px 20px rgba(102, 126, 234, 0.3)'
    }}
    {...props}
  >
    <Box direction="row" align="center" gap="medium" className="header-content">
      <HomeIcon className="home-icon" size="large" color="white" />
      <a style={{ color: 'inherit', textDecoration: 'inherit'}} href="/">
        <Heading level='2' margin='none' className="hms-title" color="white" weight="600">
          Hospital Management System
        </Heading>
      </a>
    </Box>
  </Box>
);
export class CreateAccount extends Component {
  constuctor() {
  }

  render() {

    return (
      <Grommet theme={theme} full>
        <Box fill style={{ background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)' }}>
          <AppBar />
          <Box
            fill
            align="center"
            justify="center"
            pad="medium">
            <Box className="modern-form" elevation="medium" round="medium" background="white">
              <Box align="center" margin={{ bottom: 'medium' }}>
                <Add size="xlarge" color="brand.dark" />
                <Heading level='2' margin={{ top: 'small', bottom: 'none' }} color="text.dark">
                  Create Account
                </Heading>
                <Text color="text.light" textAlign="center">
                  Patient Registration Form
                </Text>
              </Box>
              
              <Form
                onReset={event => console.log(event)}
                method="post"
                onSubmit={({ value }) => {
                  console.log("Submit", value);

                  fetch("http://localhost:3001/checkIfPatientExists?email=" + value.email)
                    .then(res => res.json())
                    .then(res => {
                      console.log(res.data[0]);

                      if ((res.data[0])) {
                        window.alert("An account is already associated with that email.");
                        console.log("no user found");
                      } else {
                        fetch("http://localhost:3001/makeAccount?name=" + value.firstName + "&lastname=" + value.lastName + "&email=" + value.email
                          + "&password=" + value.password + "&address=" + value.address + "&gender=" + value.gender
                          + "&conditions=" + value.conditions + "&medications=" + value.medications + "&surgeries=" + value.surgeries);
                        window.location = "/Home";
                      }
                    });
                }}>
                
                <Box gap="medium">
                  <Box direction="row" gap="medium">
                    <FormField
                      label="First Name"
                      name="firstName"
                      placeholder="Enter first name"
                      required
                      validate={{ regexp: /^[a-z]/i }}
                      flex
                    />
                    <FormField
                      label="Last Name"
                      name="lastName"
                      required
                      placeholder="Enter last name"
                      validate={{ regexp: /^[a-z]/i }}
                      flex
                    />
                  </Box>
                  
                  <FormField
                    label="Gender"
                    name="gender"
                    placeholder="Female or Male"
                    required
                  />
                  
                  <FormField
                    label="Email Address"
                    name="email"
                    type="email"
                    placeholder="Enter your email"
                    required
                  />
                  
                  <FormField
                    label="Password"
                    name="password"
                    type="password"
                    placeholder="Create a secure password"
                    required
                    validate={{ regexp: /^(?=.{8,})(?=.*[0-9]{2})/, message: "At least 8 characters containing 2 digits" }}
                  />
                  
                  <FormField
                    label="Address"
                    name="address"
                    placeholder="Enter your address"
                    required
                  />
                  
                  <Heading level="4" margin={{ top: 'medium', bottom: 'small' }} color="text.dark">
                    Medical History (Optional)
                  </Heading>
                  
                  <FormField
                    label="Medical Conditions"
                    name="conditions"
                    placeholder="Any existing medical conditions"
                  />
                  
                  <FormField
                    label="Previous Surgeries"
                    name="surgeries"
                    placeholder="List any previous surgeries"
                  />
                  
                  <FormField
                    label="Current Medications"
                    name="medications"
                    placeholder="List current medications"
                  />
                  
                  <Box gap="small" margin={{ top: 'medium' }}>
                    <Button
                      label="Create Account"
                      fill="horizontal"
                      type="submit"
                      primary
                      size="large"
                      className="professional-button"
                    />
                    <Button
                      label="Cancel"
                      fill="horizontal"
                      href="/"
                      size="large"
                      style={{ 
                        border: '2px solid #667eea',
                        color: '#667eea',
                        background: 'transparent'
                      }}
                    />
                  </Box>
                  
                  <Box align="center" pad="medium" margin={{ top: 'small' }}>
                    <Text color="text.light" textAlign="center" margin={{ bottom: 'small' }}>
                      Are you a healthcare professional?
                    </Text>
                    <Button
                      label="Register as Doctor"
                      href="/MakeDoc"
                      style={{ 
                        border: '2px solid #27ae60',
                        color: '#27ae60',
                        background: 'transparent'
                      }}
                    />
                  </Box>
                </Box>
              </Form>
            </Box>
          </Box>
        </Box>
      </Grommet>
    );
  }
}

export default CreateAccount;
